// Remove Nth Node From End in one pass
let list = AnimatedLinkedList<Int>()
for val in 1...5 {
    list.append(val)
}
let n = 2

func removeNthFromEnd(_ l: AnimatedLinkedList<Int>, _ n: Int) {
    guard !l.isEmpty, n > 0, n <= l.count else { return }
    let targetIndex = l.count - n
    l.remove(at: targetIndex)
}

removeNthFromEnd(list, n)
list.traverse()
